mapper.insert:

	        SELECT CONCAT('DH', EXTRACT(EPOCH FROM now())::int, LPAD(CAST(NEXTVAL('dtmeta.seq_tb_meta_data') AS varchar), 6, '0')) 

		INSERT /* SQL_ID: MetadataChgHstMapper.insertMetadataChgHstAutoKey */
		       INTO dtmeta.tb_meta_datachghst
			 ( medata_chg_hst_id
             , medata_set_id
             , prpty_id
             , val_model_id
             , medata_id
             , chg_hst_div_mtcd
             , chg_aftr_rvsn
             , chg_aftr_lang_mtcd
             , chg_aftr_val

             , chg_aftr_geo_val

             , chg_hst_regr_id
             , chg_hst_regr_nm
             , chg_hst_reg_dt
			 ) VALUES 
			 ( 
			   #{medataChgHstId}			 			 
			 , #{medataSetId}
			 , #{prptyId}
			 , #{valModelId}
			 , #{medataId}
			 , #{chgHstDivMtcd}
			 , #{chgAftrRvsn}
			 , #{chgAftrLangMtcd}
			 , #{chgAftrVal}

			 , dtmeta.ST_GeomFromGeoJSON(#{chgAftrGeoVal})	

             , #{chgHstRegrId}
             , #{chgHstRegrNm}
             , current_timestamp
			 )

INSERT /* SQL_ID: MetadataChgHstMapper.insertMetadataChgHstAutoKeyListBySelectingBySetId */ INTO dtmeta.tb_meta_datachghst ( medata_chg_hst_id , medata_set_id , prpty_id , val_model_id , medata_id , chg_hst_div_mtcd , chg_aftr_rvsn , chg_aftr_lang_mtcd , chg_aftr_val , chg_aftr_geo_val , chg_hst_regr_id , chg_hst_regr_nm , chg_hst_reg_dt ) SELECT CONCAT('DH', EXTRACT(EPOCH FROM now())::int, LPAD(CAST(NEXTVAL('dtmeta.seq_tb_meta_data') AS varchar), 6, '0')) AS medata_chg_hst_id , t1.medata_set_id , t1.prpty_id , t1.val_model_id , t1.medata_id , #{chgHstDivMtcd} , #{chgAftrRvsn} , t1.lang_mtcd , t1.medata_val , t1.geodata_val , #{chgHstRegrId} , #{chgHstRegrNm} , current_timestamp FROM dtmeta.tb_meta_data t1 WHERE t1.medata_set_id = #{medataSetId}
AND t1.prpty_id = #{prptyId}
AND t1.medata_val IN #{item}
AND ( t1.medata_val = #{item.medataVal} AND t1.lang_mtcd = #{item.langMtcd} )
AND t1.prpty_id NOT IN ( SELECT t3.prpty_id FROM dtmeta.tb_meta_dataset t1 INNER JOIN dtmeta.tb_meta_model t2 ON t1.model_id = t2.model_id INNER JOIN dtmeta.tb_meta_modelproperty t3 ON t1.model_id = t3.model_id AND t3.model_prpty_del_yn = 'N' INNER JOIN dtmeta.tb_meta_propertydefine t4 ON t3.prpty_id = t4.prpty_id AND t4.prpty_def_chg_yn = 'N' INNER JOIN dtmeta.tb_meta_model t5 ON t4.range_model_id = t5.model_id INNER JOIN dtmeta.tb_portal_code c1 ON t5.data_type_mtcd = c1.mtcd AND c1.mtcd_grp_id = 'MCG00013' WHERE t1.medata_set_id = #{medataSetId} )
ORDER BY t1.medata_id
